export const changeViews={
 'city-change-deindustrialisation':[['container','Containers and docks'],['automation','Output and jobs'],['relocation','Changing location'],['renewal','Different new jobs']],
 'city-change-inequality':[['skills','Unequal opportunities'],['budget','Resources after costs'],['poverty','Poverty measures'],['access','Quality of life']],
 'city-change-retail':[['centre','Where are the centres?'],['edge','Shopping access'],['online','Order to doorstep'],['adapt','Changing uses']],
 'city-change-sustainable-neighbourhoods':[['travel','Healthy Streets'],['target','Observed share and target'],['skills','Skills and services'],['materials','Keep materials useful']],
 'city-change-sustainable-housing':[['heat','Heat loss and fresh air'],['affordability','Cost and resources'],['wholelife','Whole-life comparison'],['balance','Homes and needs']]
};
export const changeRequirements=Object.fromEntries(Object.entries(changeViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const changeAnimated=(k,v)=>k==='city-change-deindustrialisation'?v!=='renewal':k==='city-change-inequality'?['skills','access'].includes(v):k==='city-change-retail'?v!=='centre':k==='city-change-sustainable-neighbourhoods'?v!=='target':k==='city-change-sustainable-housing'?v==='heat':false;
export const changeData={poverty:{period:'Three-year averages to 2023/24',threshold:60,before:15,after:26},travel:{unit:'% of all trips in London',observations:[{year:2019,value:63.6},{year:2024,value:63.4}],target:{year:2041,value:80}},carbon:{unit:'invented carbon units',years:5,retrofit:{embodied:60,annual:20},replacement:{embodied:90,annual:10}}};
export const wholeLife=(embodied,annual,years)=>embodied+annual*years;
const text=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const path=(d,c='#b6ccd4',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const disc=(x,y,r=6,c='#edb19b')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#e8ece7" stroke-width="1"/>`;
const box=(x,y,w,a,b='')=>`<rect x="${x}" y="${y}" width="${w}" height="${b?70:45}" rx="12" fill="#35576b" stroke="#a9c4cd"/>`+text(x+12,y+27,a,12)+(b?text(x+12,y+52,b,11):'');
const fig=(b,c)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#edf1ef" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
const link=(u,l)=>`<a href="${u}" target="_blank" rel="noopener">${l}</a>`;
const source=(k)=>`<p class="geo-caption">${{
 industrial:link('https://www.londonmuseum.org.uk/collections/london-stories/west-india-docks/','London Museum: West India Docks')+' · '+link('https://www.london.gov.uk/sites/default/files/gla_capital_gains_report_.pdf','GLA: Docklands redevelopment'),
 poverty:link('https://trustforlondon.org.uk/data/poverty-before-and-after-housing-costs/','Trust for London / DWP, 2023/24 comparison')+' · '+link('https://www.london.gov.uk/media/110897/download','GLA affordable homes evidence')+'. Three-year averages to 2023/24; relative income threshold 60% of the median, not the alternative 50% measure. Two definitions, not individual causal tracking.',
 retail:link('https://www.london.gov.uk/sites/default/files/high_streets_for_all_report_web_final.pdf','GLA: High Streets for All, 2017')+' · '+link('https://www.london.gov.uk/programmes-strategies/planning/london-plan/the-london-plan-2021-online/chapter-2-spatial-development-patterns','London Plan 2021: town centres')+'. Dated evidence on mechanisms; old projections are not measured outcomes.',
 travel:link('https://apps.london.gov.uk/state-of-london/report/transport','GLA / TfL: transport evidence')+' · '+link('https://tfl.gov.uk/corporate/about-tfl/the-mayors-transport-strategy','Mayor’s Transport Strategy')+'. All trips by all people travelling in London, not journey stages or only residents. Selected observed years; 2041 is a target, not a forecast or result.',
 services:link('https://tfl.gov.uk/corporate/about-tfl/how-we-work/planning-for-the-future/healthy-streets','TfL Healthy Streets')+' · '+link('https://www.london.gov.uk/programmes-strategies/communities-and-social-justice/help-cost-living/employment-and-training-opportunities','GLA: training and employment')+' · '+link('https://www.london.gov.uk/what-we-do/planning/implementing-london-plan/london-plan-guidance-and-spgs/circular-economy-statement-guidance-consultation-draft','GLA: circular economy'),
 housing:link('https://www.warmer-homes.london/','Warmer Homes London')+' · '+link('https://www.gov.uk/government/publications/warm-homes-plan/warm-homes-plan-html','Warm Homes Plan: fabric and ventilation')+' · '+link('https://www.london.gov.uk/programmes-strategies/planning/london-plan/the-london-plan-2021-online/chapter-4-housing','London Plan 2021: affordable housing')+'. Programme and policy examples; distinguish aims from homes actually improved.'
 }[k]}</p>`;
const roof=(x,y,w=100)=>`<path d="M${x} ${y+40}L${x+w/2} ${y} ${x+w} ${y+40}V${y+140}H${x}Z" fill="#a6bfb1" stroke="#d9e4dc" stroke-width="2"/><rect x="${x+18}" y="${y+65}" width="24" height="32" rx="3" fill="#315367"/><rect x="${x+60}" y="${y+92}" width="23" height="48" fill="#315367"/>`;
const person=(x,y,c='#f0b69f')=>disc(x,y,5,c)+path(`M${x} ${y+7}V${y+25}m-8-12h16m-8 12-7 13m7-13 7 13`,c,3);
const title=(s)=>text(20,28,s,14);
export function changeEvidence(k='poverty'){
 let b='',caption='',rows=[];
 if(k==='poverty'){b=title('LONDON · TWO POVERTY MEASURES')+text(20,52,'Population share (%) · common 0–100 scale',12);for(const[i,[n,v]]of[['Before housing costs',15],['After housing costs',26]].entries()){const y=90+i*90;b+=text(25,y,n,13)+`<rect x="25" y="${y+14}" width="${v*3.6}" height="30" rx="5" fill="${i?'#eab09a':'#a6c8bf'}"/>`+text(35+v*3.6,y+35,v+'%',14);}b+=path('M25 290H385','#a8c1cb',1)+text(22,312,'0',11)+text(195,312,'50',11)+text(370,312,'100',11)+text(20,338,'Three-year averages to 2023/24 · 60% threshold',11);caption='Two defined relative-poverty indicators from the same dated source. Read the denominator and housing-cost treatment; these are not percentages of land or unemployment rates.';rows=[['Before housing costs','15%'],['After housing costs','26%']];}
 else if(k==='travel'){b=title('LONDON · SUSTAINABLE TRIP SHARE')+text(20,52,'Walking, cycling and public transport (%)',12);for(const[i,[n,v,target]]of[['2019',63.6,false],['2024',63.4,false],['2041 target',80,true]].entries()){const y=84+i*65;b+=text(20,y,n,12)+`<rect x="130" y="${y-17}" width="${v*3}" height="28" rx="4" fill="${target?'none':'#aac9c0'}" stroke="${target?'#efb59e':'#d1dfd9'}" ${target?'stroke-dasharray="5 4"':''}/>`+text(140+v*3,y+3,v.toFixed(1)+'%',12);}b+=path('M130 287H430','#a8c1cb',1)+text(126,308,'0',11)+text(272,308,'50',11)+text(407,308,'100',11)+text(20,338,'Solid: observed · dashed: future policy target',11);caption='Selected observed trip shares for 2019 and 2024, with a separately labelled future target. No intermediate annual values or journey-stage totals are implied.';rows=[['2019 observed','63.6%'],['2024 observed','63.4%'],['2041 target','80%']];}
 else{b=title('INVENTED WHOLE-LIFE CARBON INPUTS')+text(20,52,'Same five-year period · illustrative units',12)+text(20,105,'Option',12)+text(180,105,'Embodied',12)+text(295,105,'Each year',12)+path('M20 119H420','#a8c1cb',1)+text(20,158,'Retrofit',14)+text(200,158,'60',14)+text(320,158,'20',14)+text(20,215,'Replacement',14)+text(200,215,'90',14)+text(320,215,'10',14)+text(20,285,'Embodied once + annual operational × years',12)+text(20,327,'Not measured London projects or a full footprint',11);caption='Invented carbon inputs for a consistent five-year comparison. Units are illustrative; calculate totals using the same boundary and period. Not an assessment of an actual building project.';rows=[['Retrofit embodied','60 units'],['Retrofit annual','20 units/year'],['Replacement embodied','90 units'],['Replacement annual','10 units/year'],['Assessment period','5 years']];}
 return fig(b,caption)+(k==='carbon'?'':source(k))+`<details class="geo-chart-values"><summary>Read the comparison values</summary><table class="geo-data"><caption>${k==='carbon'?'Invented teaching inputs':'Dated source comparison'}</caption><thead><tr><th scope="col">Measure</th><th scope="col">Value</th></tr></thead><tbody>${rows.map(([a,v])=>`<tr><th scope="row">${a}</th><td>${v}</td></tr>`).join('')}</tbody></table></details>`;
}
export function changeScene(k,v,t=0){if(!changeViews[k])return '';if(!changeRequirements[k].includes(v))v=changeRequirements[k][0];t=changeAnimated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='',src='';
 if(k==='city-change-deindustrialisation'){
 src='industrial';
 if(v==='container'){b=title('CARGO TECHNOLOGY CHANGES PORT ADVANTAGE')+`<rect x="20" y="205" width="400" height="80" fill="#5b8ba3"/><path d="M35 195h140l-15 28H55Z" fill="#bdc9c3"/><rect x="50" y="173" width="40" height="20" fill="#d8b395"/><rect x="95" y="173" width="40" height="20" fill="#a9c5b7"/><path d="M220 160h195l-15 60H235Z" fill="#8fb2c3"/>`+Array.from({length:6},(_,i)=>`<rect x="${235+i%3*50}" y="${105+Math.floor(i/3)*26}" width="45" height="23" fill="${i%2?'#dcb395':'#aac6b6'}"/>`).join('')+path('M230 78H390V105m-160-27V54h-40v122','#c7d9df',4)+`<rect x="${195+150*t}" y="${68+20*t}" width="36" height="20" fill="#efb69b"/>`+text(20,70,'Older enclosed docks',12)+text(230,260,'Larger container facilities',12)+text(20,326,'Symbolic comparison · not real ship sizes or cargo rates',11);c='Container handling and ship size changed port requirements. Tilbury could serve cargo that older enclosed docks struggled to handle. The crane motion isolates a mechanism, not a measured volume or exact dock layout.';}
 else if(v==='automation'){const workers=Math.round(10-5*t);b=title('SAME OUTPUT, FEWER WORKERS · TOY CASE')+text(20,70,'Output stays at 100 units per period',15)+Array.from({length:10},(_,i)=>person(40+i%5*75,110+Math.floor(i/5)*85,i<Math.round(workers)?'#eeb69e':'#526b7c')).join('')+text(20,286,'Workers: '+workers.toFixed(0),16)+text(220,286,'Units / worker: '+(100/workers).toFixed(1),14)+text(20,331,'End: 5 workers, 20 units each · not a London dataset',11);c='Invented productivity example: total output remains 100 while labour falls from 10 to 5. Technology can reduce employment without eliminating production. Intermediate frames are illustrative, not measured industrial history.';}
 else if(v==='relocation'){b=title('RELOCATION HAS MORE THAN ONE SCALE')+box(20,70,180,'Central site','Congestion / high land cost')+box(240,70,180,'Outer or regional site','Space / road access')+path('M100 170H340')+disc(100+240*t,170,8)+box(75,230,290,'Global production networks','Costs / suppliers / international competition')+text(20,330,'A move away from the centre need not go abroad',12);c='A symbolic firm moves away from a central site; global sourcing is a separate, potentially interacting influence. These are causal possibilities, not a mapped firm relocation or a universal account of every factory closure.';}
 else{b=title('NEW ACTIVITY, DIFFERENT REQUIREMENTS')+box(20,75,180,'Former dock work','Cargo handling / trade skills')+box(240,75,180,'New office activity','Varied professional skills')+path('M110 165Q220 235 330 165','#aec9cd',3)+box(70,245,300,'Connect people to opportunity','Training / travel / recruitment / housing');c='Docklands redevelopment introduced new functions, but jobs are not automatically interchangeable. Evaluate access and resident outcomes alongside buildings and investment.';}
 }
 if(k==='city-change-inequality'){
 if(v==='poverty')return changeEvidence('poverty');src='poverty';
 if(v==='skills'){b=title('GROWTH DOES NOT GIVE EQUAL ACCESS')+box(20,65,180,'Residents with access','Skills / networks / travel')+box(240,65,180,'Barriers to access','Costs / care / recruitment')+box(120,245,200,'Changing jobs','Different pay and security')+path('M110 145L180 237M330 145L260 237')+disc(110+70*t,145+92*t,7)+disc(330-70*t*.45,145+92*t*.45,7)+text(20,330,'Illustrative pathways, not a ranking of individuals',11);c='Two symbolic routes show how barriers can prevent equal access to expanding employment. No personal group is assigned a fixed ability or outcome; policies and employer practices can change access.';}
 else if(v==='budget'){b=title('SAME COST, DIFFERENT REMAINING RESOURCES')+box(20,75,180,'Household A','Income 500; costs 300')+box(240,75,180,'Household B','Income 800; costs 300')+text(40,218,'Remaining: 200',17)+text(260,218,'Remaining: 500',17)+text(20,285,'Invented weekly money units; needs also differ',12)+text(20,330,'Not the official equivalised-income poverty calculation',11);c='Invented budgets isolate resources after costs: 500−300=200 and 800−300=500. Actual living standards depend on household composition, other costs and security. These are not observed London households or an official poverty threshold.';}
 else{b=title('QUALITY OF LIFE HAS SEVERAL DIMENSIONS')+box(20,65,185,'Housing and resources','Space / security / income')+box(235,65,185,'Health and surroundings','Air / safety / public space')+box(20,225,185,'Education and services','Availability and quality')+box(235,225,185,'Employment access','Travel / skills / hours')+path('M110 150L330 215M330 150L110 215')+disc(110+220*t,150+65*t)+disc(330-220*t,150+65*t);c='Connections show interacting dimensions, not a numerical quality-of-life score. Compare groups and places over time; a borough mean or high building value does not describe every resident.';}
 }
 if(k==='city-change-retail'){
 src='retail';
 if(v==='centre'){b=title('SHOPPING CENTRES ARE NOT ONE CATEGORY')+box(20,65,400,'West End','Central London: retail, culture, offices and tourism')+box(20,165,190,'Westfield Stratford','Within urban London')+box(230,165,190,'Lakeside, Thurrock','Outside Greater London')+path('M115 240H325','#a6c3d0',2)+text(20,300,'Compare function, location, catchment and transport',12)+text(20,330,'Conceptual classification, not a map or retail ranking',11);c='Selected named contrasts distinguish central, urban and outside-London locations. A large mall is not automatically out-of-town, and these boxes do not map actual footprints.';}
 else if(v==='edge'){b=title('SHOPPING CHOICES REDISTRIBUTE ACTIVITY')+box(20,70,180,'Traditional centre','Local shops / services')+box(240,70,180,'Peripheral retail','Larger sites / access')+box(125,235,190,'Households','Different travel needs')+path('M210 225L110 155M230 225L330 155')+disc(210-100*t,225-70*t)+disc(230+100*t,225-70*t)+text(20,330,'Journeys and local effects vary; no measured flow',11);c='Different shoppers can use different centres. Peripheral access and store variety may redirect some spending, but effects depend on transport and catchments; older centres do not all close.';}
 else if(v==='online'){b=title('ONLINE PURCHASES STILL MOVE GOODS')+box(20,70,180,'Order / warehouse','Digital transaction')+box(240,70,180,'Home / collection','Delivery destination')+path('M105 180H335M335 250H105','#b3cdd5',3)+`<rect x="${105+230*t}" y="166" width="22" height="22" rx="3" fill="#edb49c"/>`+disc(335-230*t,250,6,'#a7cabe')+text(20,285,'Outbound delivery →     ← some returns',12)+text(20,330,'Compare deliveries, returns and shopping trips replaced',11);c='The parcel and return route are symbolic. A web purchase can replace a shopping trip but adds logistics and packaging; distance, load and return patterns affect total impact. Not every parcel is returned.';}
 else{b=title('RETAIL SPACE CAN GAIN NEW USES')+`<rect x="35" y="90" width="370" height="130" rx="8" fill="#8aa79e"/><path d="M35 90h370v35H35Z" fill="#d6b29e"/>`+Array.from({length:4},(_,i)=>`<rect x="${50+i*90}" y="145" width="70" height="70" fill="${i<Math.floor(t*4)?'#abcfc1':'#35566c'}" stroke="#d6e2dd"/>`).join('')+text(47,252,'Shop',12)+text(135,252,'Clinic',12)+text(225,252,'Library',12)+text(322,252,'Cafe',12)+text(20,300,'Different reasons to visit; judge local need and access',12)+text(20,330,'Illustrative reuse, not one actual planning scheme',11);c='Lighting units in sequence illustrates diversification of a fictional high street. New services and leisure can support visits, while loss of affordable shops can harm some users; this is not measured regeneration or a prescribed plan.';}
 }
 if(k==='city-change-sustainable-neighbourhoods'){
 if(v==='target')return changeEvidence('travel');src='services';
 if(v==='travel'){b=title('HEALTHY STREETS: MAKE ACCESS EASIER')+`<rect x="20" y="90" width="400" height="150" rx="10" fill="#5a7783"/><path d="M20 118H420M20 210H420" stroke="#a4c0b4" stroke-width="25"/><path d="M195 133v62m12-62v62m12-62v62m12-62v62" stroke="#e3e8df" stroke-width="6"/>`+`<rect x="${45+250*t}" y="151" width="65" height="32" rx="8" fill="#e5b397"/>`+person(60+275*t,92,'#e9ece3')+disc(70+270*t,217,6,'#f0bd9e')+disc(90+270*t,217,6,'#f0bd9e')+text(20,279,'Walking / wheeling · cycling · public transport',12)+text(20,309,'Safety, seating, access and reliable links matter',12);c='Schematic routes illustrate choices supported by accessible streets and transport. Movement is not traffic simulation or a measured emission reduction; designs must suit varied journeys and abilities.';}
 else if(v==='skills'){b=title('SKILLS AND SERVICES CONNECT OPPORTUNITY')+box(20,70,180,'College / training','Skills and confidence')+box(240,70,180,'Work and services','Vacancies / health / support')+path('M105 180H335')+disc(105+230*t,180,7)+box(55,240,330,'Make participation possible','Accessible travel / childcare / staff / funding');c='Training can improve employment access; nearby education and health services support daily wellbeing. The moving learner is hypothetical, and course participation is not a guaranteed job or health outcome.';}
 else{const leg=Math.min(2,Math.floor(t*3)),u=t===1?1:t*3-leg,points=[[105,145],[335,145],[220,235],[105,145]],px=points[leg][0]+(points[leg+1][0]-points[leg][0])*u,py=points[leg][1]+(points[leg+1][1]-points[leg][1])*u;b=title('RETAIN VALUE, THEN RECYCLE MATERIALS')+box(20,60,180,'Use / repair','Keep products useful')+box(240,60,180,'Reuse / share','Extend product life')+box(130,240,180,'Recycle materials','Collect / sort / reprocess')+path('M105 145H335L220 235Z','#a8c6c6',3)+disc(px,py,8)+text(20,335,'Energy, losses and residual waste remain',12);c='A looping material token shows a circular-economy aim, not perfect conservation of value or a measured London recycling rate. Prevention, repair and reuse differ from reprocessing; losses, collection and energy still matter.';}
 }
 if(k==='city-change-sustainable-housing'){
 src='housing';
 if(v==='wholelife')return changeEvidence('carbon');
 if(v==='heat'){const loss=55-30*t;b=title('FABRIC, COMFORT AND HEALTHY AIR')+roof(165,95,110)+`<path d="M165 230V135L220 95 275 135V230" stroke="#e7ba95" stroke-width="${3+8*t}" fill="none"/>`+path(`M170 160L${170-loss} 160m${loss} 35L${170-loss} 195`,'#efb49b',4)+path(`M270 160L${270+loss} 160m-${loss} 35L${270+loss} 195`,'#efb49b',4)+path('M205 125Q220 75 240 125','#add7e0',3)+disc(205+35*t,125-35*Math.sin(t*Math.PI),5,'#a7d4e0')+text(20,72,'Thicker fabric: less heat loss for the same conditions',12)+text(20,285,'Ventilation and moisture control remain important',12)+text(20,330,'Symbolic arrows, not measured heat or air-flow rates',11);c='The before-to-after loop illustrates reduced fabric heat loss alongside ventilation. It is not a retrofit design or fixed bill-saving estimate. Actual measures must address moisture, healthy air and summer conditions.';}
 else if(v==='affordability'){b=title('LOW ENERGY IS NOT THE SAME AS AFFORDABLE')+box(20,85,180,'Housing / running cost','300 invented units/week')+box(240,85,180,'Household resources','500 invented units/week')+text(85,230,'Remaining resources: 200',19)+text(20,285,'Rent, tenure, security and other needs also matter',12)+text(20,330,'Not an eligibility rule or observed household budget',11);c='An invented affordability illustration:500−300=200remaining. Efficient homes can still cost more than some households can afford; a complete judgement needs needs, tenure and other essential costs.';}
 else{b=title('COMPARE DELIVERY WITH LOCAL NEED')+box(20,70,180,'Announced homes','A commitment to deliver')+box(240,70,180,'Completed homes','Built and allocated')+box(60,235,320,'Who can live there?','Cost / size / access / security / local need')+path('M110 155L180 225M330 155L260 225')+text(20,330,'Track outputs and resident outcomes, not only targets',11);c='A housing target or announcement is not a home already occupied. Compare funding, completions, allocation and resident outcomes; assess disruption and the needs of existing residents as well as new demand.';}
 }
 return fig(b,c)+(src?source(src):'');
}
